package com.lqq.supportflow.eventing.api;
import com.lqq.supportflow.eventing.*; import com.lqq.supportflow.eventing.application.DispatchOutboxService; import com.lqq.supportflow.shared.AuthenticatedPrincipal; import java.util.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/outbox") public class AdminOutboxController { private final DispatchOutboxService service; private final OutboxService outbox; public AdminOutboxController(DispatchOutboxService service,OutboxService outbox){this.service=service;this.outbox=outbox;} @PostMapping("/dispatch") Map<String,Integer> dispatch(@RequestParam(defaultValue="100") int limit){if(limit<1||limit>1000)throw new IllegalArgumentException("dispatch limit must be between 1 and 1000");return Map.of("published",service.dispatch(limit));} @GetMapping("/failed") List<FailedOutboxEvent> failed(@AuthenticationPrincipal AuthenticatedPrincipal principal,@RequestParam(defaultValue="100") int limit){if(limit<1||limit>1000)throw new IllegalArgumentException("limit must be between 1 and 1000");return outbox.failed(principal.tenantId(),limit);}}
